ACK 55d3cd51a48d1a8979b2fb542a0e8dc5fe793398

Suggestion for a follow-up PR: a test verifying that disallowed clients are rejected immediately after `accept()`, before any request bytes are read

<details>
<summary>diff</summary>

```diff
diff --git a/src/test/httpserver_tests.cpp b/src/test/httpserver_tests.cpp
index cd020fc60c..bce800f205 100644
--- a/src/test/httpserver_tests.cpp
+++ b/src/test/httpserver_tests.cpp
@@ -631,6 +631,59 @@ BOOST_AUTO_TEST_CASE(http_server_socket_tests)
     server.StopListening();
 }

+BOOST_AUTO_TEST_CASE(http_server_rejects_disallowed_client_before_read)
+{
+    // DynSock reports accepted connections as coming from 5.5.5.5.
+    gArgs.ForceSetArg("-rpcallowip", "1.1.1.1");
+
+    std::atomic_bool request_dispatched{false};
+    HTTPServer server{[&request_dispatched](std::unique_ptr<HTTPRequest>&&) {
+        request_dispatched = true;
+    }};
+    BOOST_REQUIRE(server.InitHTTPAllowList());
+
+    CService addr_bind{Lookup("0.0.0.0", /*portDefault=*/0, /*fAllowLookup=*/false).value()};
+    BOOST_REQUIRE(server.BindAndStartListening(addr_bind));
+    server.StartSocketsThreads();
+
+    // Queue a complete request. The server should close this socket immediately after
+    // accept(), without creating an HTTPRemoteClient or reading any request bytes.
+    std::shared_ptr<DynSock::Pipes> mock_client_socket_pipes{
+        ConnectClient(std::as_bytes(std::span(full_request)))};
+
+    bool disconnected{false};
+    for (int attempts{1000}; attempts > 0; --attempts) {
+        char byte;
+        const ssize_t bytes_read{mock_client_socket_pipes->send.GetBytes(&byte, sizeof(byte), MSG_PEEK)};
+        if (bytes_read == 0) {
+            disconnected = true;
+            break;
+        }
+        if (bytes_read > 0) {
+            break;
+        }
+        std::this_thread::sleep_for(10ms);
+    }
+
+    const size_t connections{server.GetConnectionsCount()};
+
+    server.InterruptNet();
+    server.JoinSocketsThreads();
+    const bool dispatched{request_dispatched.load()};
+    server.ClearConnectedClients();
+    server.StopListening();
+
+    BOOST_CHECK(disconnected);
+    BOOST_CHECK_EQUAL(connections, 0);
+    BOOST_CHECK(!dispatched);
+
+    std::string unread_request(full_request.size(), '\0');
+    BOOST_REQUIRE_EQUAL(
+        mock_client_socket_pipes->recv.GetBytes(unread_request.data(), unread_request.size()),
+        static_cast<ssize_t>(full_request.size()));
+    BOOST_CHECK_EQUAL(unread_request, std::string{full_request});
+}
+
 BOOST_AUTO_TEST_CASE(http_socket_error_tests)
 {
